import { env } from '$env/dynamic/private';
import { json } from '@sveltejs/kit';
import type { Handle, HandleServerError } from '@sveltejs/kit';
import { validateDebugToken } from '$lib/server/debug-helpers';

export const handle: Handle = async ({ event, resolve }) => {
  // Debug API auth — gate /api/debug/* behind Bearer token
  if (event.url.pathname.startsWith('/api/debug/')) {
    const auth = event.request.headers.get('authorization');
    if (!validateDebugToken(auth, env.DEBUG_API_TOKEN)) {
      return json({ error: 'Unauthorized' }, { status: 401 });
    }
  }

  const response = await resolve(event);
  if (
    event.request.method === 'GET' &&
    (response.headers.get('content-type') ?? '').includes('text/html')
  ) {
    // If the request carries the recently-viewed cookie the response is personalised,
    // so it must not be stored in a shared cache (CDN). Non-cookied visitors (first-time
    // or cleared) are safe to cache publicly.
    const personalized = event.request.headers.get('cookie')?.includes('rv=') ?? false;
    response.headers.set(
      'Cache-Control',
      personalized
        ? 'private, max-age=0'
        : 'public, max-age=0, s-maxage=30, stale-while-revalidate=60',
    );
  }
  return response;
};

export const handleError: HandleServerError = ({ error, event, status }) => {
  // Log server-side errors with context (avoids leaking stack traces to the client)
  const message = error instanceof Error ? error.message : 'Unknown error';
  console.error(`[server error] ${status} on ${event.url.pathname}: ${message}`);

  // Return a safe, generic message to the client
  return {
    message: status === 404 ? 'Not found' : 'An unexpected error occurred',
  };
};

import { env } from '$env/dynamic/private';
import { env as publicEnv } from '$env/dynamic/public';
import type { LayoutServerLoad } from './$types';
import { db, airports } from '$lib/server/db';

const AIRPORTS_TTL_MS = 5 * 60 * 1000; // 5 minutes

interface AirportCache {
  data: Record<string, {
    iataCode: string;
    icaoCode: string | null;
    name: string;
    city: string | null;
    latitude: number | null;
    longitude: number | null;
  }>;
  expiresAt: number;
}

let airportsCache: AirportCache | null = null;

async function getCachedAirports(): Promise<AirportCache['data']> {
  if (airportsCache && Date.now() < airportsCache.expiresAt) return airportsCache.data;
  const rows = await db
    .select({
      iataCode: airports.iataCode,
      icaoCode: airports.icaoCode,
      name: airports.name,
      city: airports.city,
      latitude: airports.latitude,
      longitude: airports.longitude,
    })
    .from(airports);
  const data = Object.fromEntries(rows.map(a => [a.iataCode, a]));
  airportsCache = { data, expiresAt: Date.now() + AIRPORTS_TTL_MS };
  return data;
}

export const load: LayoutServerLoad = async (_) => {
  const domain = env.DOMAIN || 'airways.gg';

  const airportsMap = await getCachedAirports();

  return {
    siteUrl: `https://${domain}`,
    buyMeACoffeeUrl: publicEnv.PUBLIC_BUY_ME_A_COFFEE_URL || null,
    umamiWebsiteId: publicEnv.PUBLIC_UMAMI_WEBSITE_ID || null,
    umamiUrl: publicEnv.PUBLIC_UMAMI_URL || null,
    airports: airportsMap,
  };
};

